/**
 * DesignForge AI - Design Token Compiler
 * Compiles design tokens into CSS Custom Properties (:root, theme modes) and TypeScript constants
 */

export class TokenCompiler {
  constructor(tokens = []) {
    this.tokens = tokens;
  }

  /**
   * Compiles tokens into CSS Custom Properties
   */
  compileCss() {
    const lines = [
      '/**',
      ' * Generated by DesignForge AI React Compiler',
      ' * Design Token CSS Custom Properties',
      ' */',
      ':root {'
    ];

    const tokenMap = new Map();

    for (const collection of this.tokens) {
      lines.push(`  /* Collection: ${collection.name || collection.id} */`);
      for (const t of collection.tokens || []) {
        const cssVar = this.tokenToCssVarName(t.id || t.name);
        const val = this.formatTokenValue(t.type, t.value);
        lines.push(`  ${cssVar}: ${val};`);
        tokenMap.set(t.id, cssVar);
      }
    }

    lines.push('}');
    return {
      css: lines.join('\n'),
      tokenMap
    };
  }

  /**
   * Compiles tokens into TypeScript type-safe constants
   */
  compileTs() {
    const tokenObj = {};

    for (const collection of this.tokens) {
      const colKey = this.toCamelCase(collection.name || collection.id);
      tokenObj[colKey] = {};
      for (const t of collection.tokens || []) {
        const key = this.toCamelCase(t.name || t.id);
        tokenObj[colKey][key] = {
          id: t.id,
          name: t.name,
          type: t.type,
          value: t.value,
          variable: this.tokenToCssVarName(t.id || t.name)
        };
      }
    }

    return `/**
 * Generated by DesignForge AI React Compiler
 * Design Token Dictionary & Types
 */

export const designTokens = ${JSON.stringify(tokenObj, null, 2)} as const;

export type DesignTokens = typeof designTokens;
`;
  }

  tokenToCssVarName(idOrName) {
    const slug = idOrName
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    return `--${slug.startsWith('token-') ? slug : `token-${slug}`}`;
  }

  formatTokenValue(type, val) {
    if (type === 'dimension' || type === 'spacing' || type === 'radius') {
      return typeof val === 'number' ? `${val}px` : val;
    }
    return val;
  }

  toCamelCase(str) {
    return str
      .replace(/[^a-zA-Z0-9]+(.)/g, (m, chr) => chr.toUpperCase())
      .replace(/^[A-Z]/, c => c.toLowerCase());
  }
}
